save(467,dict(paragraphs=['Sreekala Sivasankaran writes poetry and fiction in Malayalam and English and also works in translation. Based in Kottayam, Kerala, she brings a background in cultural scholarship to her literary practice; she formerly served as an Associate Professor at the Indira Gandhi National Centre for the Arts in New Delhi. Her poetry collections include Samayathinte Manaltharikal, You Walk with Me, Dream of the Butterflies and Stranded.','“The Archive of Love” approaches memory as both a home and a picture held in a frame. Wounded leaves and flowers keep the marks of a storm, yet the poem moves towards a love without concealment. Its narrowing final lines slow the reading into an intimate affirmation of openness and constancy.'],sources=[source('Madras Courier — Sreekala Sivasankaran','https://madrascourier.com/author/sreekalasivasankaran/','Opened contributor bibliography identifies Kottayam, Malayalam/English fiction and poetry, translation and four named poetry collections.'),source('IGNCA — 2014 appointment order','https://ignca.gov.in/circulars/sop05_20140224_01.pdf','Indexed institutional appointment order identifies Associate Professor Sreekala Sivasankaran, Janapada Sampada Division; direct PDF fetch failed. Historical role only.','search_index'),source('Nithyakalyanipub — Conversations with Sreekala Sivasankaran','https://nithyakalyanipub.wordpress.com/2020/04/16/conversation-s/','Opened interview introduction and response on academic, artistic and literary work and first poetry publication.'),source('ThriftBooks — You Walk With Me: Poems','https://www.thriftbooks.com/w/you-walk-with-me--poems/22383930/','Indexed catalogue identifies author, October 2018 edition and ISBN 9781726759373; direct fetch failed.','search_index')],books=[dict(title='You Walk with Me: Poems',detail='Poetry · 2018 edition · ISBN 9781726759373 · Bookseller catalogue',url='https://www.thriftbooks.com/w/you-walk-with-me--poems/22383930/')],identity_match='Captured Kottayam poet-scholar identity matches journal contributor biography; uncommon full name and exact IGNCA Associate Professor role independently match institutional record.',poems_read=[dict(id=793,title='The Archive of Love',coverage='Full English original, all nineteen lines.',basis='Memory as home/canvas, storm-marked flowers and leaves, open companionship and narrowing closing lines.')],limitations=['No present institutional appointment asserted from historical contract.','Captured earlier NMML fellowship and HNLU teaching not newly corroborated; not expanded.','Book-product access is indexed metadata, not a successful direct fetch.'],research_leads=[dict(url='https://ignca.gov.in/PDF_data/aakhyan_brochure.pdf',finding='Indexed IGNCA publication credits Sreekala with introductory essay on mask, puppet and picture-showman traditions; potential extended scholarly bibliography.')],next_action='Independent author/editor review; confirm preferred current book links.'))
